const $=s=>document.querySelector(s), main=$('#main');
const courses=[{id:'science',title:'Science Explorer',thai:'เปิดโลกวิทยาศาสตร์รอบตัว',subject:'วิทยาศาสตร์',level:'ประถมปลาย',age:'9–12 ปี',lessons:8,formula:'H₂O',style:'',desc:'เริ่มต้นจากความสงสัย เชื่อมโยงวิทยาศาสตร์กับชีวิตประจำวัน ผ่านการสังเกตและการทดลองอย่างเป็นขั้นตอน',objectives:['สังเกตและตั้งคำถามอย่างมีเหตุผล','เข้าใจสสารและการเปลี่ยนแปลง','ออกแบบการทดลองอย่างปลอดภัย'],modules:['เริ่มต้นคิดแบบนักวิทยาศาสตร์','สสารและการเปลี่ยนแปลง','แรงและพลังงานรอบตัว']},{id:'physics',title:'Physics Foundations',thai:'เข้าใจฟิสิกส์จากพื้นฐาน',subject:'ฟิสิกส์',level:'มัธยมต้น',age:'12–15 ปี',lessons:10,formula:'F = ma',style:'physics',desc:'ทำความเข้าใจแรง การเคลื่อนที่ และพลังงานด้วยภาพและสถานการณ์ใกล้ตัว ก่อนต่อยอดสู่การแก้โจทย์',objectives:['อธิบายแรงและการเคลื่อนที่','อ่านกราฟระยะทางและเวลา','ประยุกต์แนวคิดเพื่อแก้ปัญหา'],modules:['การเคลื่อนที่ในชีวิตประจำวัน','แรงและกฎของนิวตัน','งานและพลังงาน']},{id:'chemistry',title:'Chemistry Essentials',thai:'เคมีที่เข้าใจได้',subject:'เคมี',level:'มัธยมปลาย',age:'15–18 ปี',lessons:12,formula:'Na⁺',style:'chem',desc:'เชื่อมโลกของอะตอมกับสิ่งที่มองเห็น เรียนรู้โครงสร้างสาร พันธะ และปฏิกิริยาเคมีทีละขั้น',objectives:['อธิบายโครงสร้างอะตอม','จำแนกพันธะเคมี','เข้าใจหลักการเกิดปฏิกิริยา'],modules:['โลกของอะตอม','พันธะเคมี','ปฏิกิริยารอบตัว']}];
const state={role:null,done:new Set([0,1,2]),lesson:3,requests:[],registrations:[],messages:[],score:null,attempts:0,assigned:true,child:'เมฆ',access:'31 ธันวาคม 2569',grade:null,feedback:'',hidden:false,publication:'ร่าง',eventCount:6};
const roles={student:'นักเรียน',parent:'ผู้ปกครอง',teacher:'ครู',admin:'ผู้ดูแลระบบ'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,url,style='dark')=>`<a class="button ${style}" href="#${url}">${text} <span>↗</span></a>`;
const empty=(title,text)=>`<div class="empty"><h3>${title}</h3><p>${text}</p></div>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$('.mobile-menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',open)};
function card(c,learning=false){return `<article class="card"><a href="#${learning?'portal/learn':'course/'+c.id}" class="course-art ${c.style}" aria-label="${c.title}"><span class="formula">${c.formula}</span><span class="art-caption">HEADSTART / ${c.subject==='เคมี'?'CHEMISTRY':c.subject==='ฟิสิกส์'?'PHYSICS':'SCIENCE'}</span></a><div class="card-body"><span class="tag">${c.subject}</span> <span class="tag gray">${c.level}</span><h3><a href="#${learning?'portal/learn':'course/'+c.id}">${c.title}</a></h3><p>${c.thai}</p>${learning?`<progress value="${state.done.size}" max="8" aria-label="ความก้าวหน้า"></progress><p>เรียนแล้ว ${state.done.size}/8 บทเรียน · ${Math.round(state.done.size/8*100)}%</p>`:''}<div class="card-foot"><span>${c.lessons} บทเรียนตัวอย่าง ${learning?'':'· '+c.age}</span><a href="#${learning?'portal/learn':'course/'+c.id}" aria-label="ดู ${c.title}">${learning?'เรียนต่อ':'ดูหลักสูตร'} <span class="arrow">↗</span></a></div></div></article>`}
function intro(k,title,desc){return `<div class="page-intro"><div class="breadcrumb"><a href="#home">หน้าแรก</a> / ${k}</div><h1>${title}</h1><p>${desc}</p></div>`}
function home(){return `<div class="container"><section class="hero"><div><div class="eyebrow">A HEAD START FOR A BRIGHTER FUTURE</div><h1>ให้ความสงสัย<br>เป็นจุดเริ่มต้นของ<br><em>การเรียนรู้ที่ไปได้ไกล</em></h1><p>ค้นพบวิทยาศาสตร์ในแบบที่เข้าใจ เชื่อมโยงความรู้กับโลกจริง และค่อย ๆ เติบโตอย่างมั่นใจไปกับ Headstart Academics</p><div class="actions">${btn('ค้นหาหลักสูตรที่ใช่','courses')}${btn('ทดลองเรียนฟรี','resources','')}</div><div class="hero-meta"><span>✓</span> เรียนรู้ตามจังหวะของตัวเอง <span>✓</span> เข้าใจมากกว่าท่องจำ</div></div><div class="hero-media"><img src="hero.png" alt="ภาพประกอบนักเรียนร่วมกันทำการทดลองวิทยาศาสตร์"><div class="floating-note"><b>✧</b><div><strong>Small questions. Big discoveries.</strong><small>ทุกคำถาม พาเราไปได้ไกลขึ้น</small></div></div><span class="image-label">ภาพประกอบสร้างด้วย AI ไม่ใช่ภาพนักเรียนของโรงเรียน</span></div></section><div class="principles"><div><b>01</b><span>เข้าใจอย่างลึกซึ้ง<small>เริ่มจากพื้นฐานที่แข็งแรง</small></span></div><div><b>02</b><span>เรียนรู้ผ่านการลงมือ<small>เชื่อมบทเรียนกับโลกจริง</small></span></div><div><b>03</b><span>เติบโตในแบบของตัวเอง<small>ติดตามพัฒนาการทีละก้าว</small></span></div><section class="section"><div class="heading-row"><div><div class="eyebrow">FIND YOUR NEXT DISCOVERY</div><h2>เริ่มต้นเส้นทางการเรียนรู้ของคุณ</h2><p>ตัวอย่างเส้นทางการเรียนรู้ ตั้งแต่ประถมปลายถึงมัธยมปลาย</p></div><a class="text-link" href="#courses">ดูหลักสูตรทั้งหมด ↗</a></div><div class="grid">${courses.map(c=>card(c)).join('')}</div></section></div><section class="section light"><div class="container split"><div class="feature-box"><div class="eyebrow" style="color:var(--green)">THE HEADSTART APPROACH</div><h2>ความเข้าใจที่ดี<br>เริ่มต้นด้วยคำว่า “ทำไม”</h2><p>พื้นที่สำหรับการตั้งคำถาม ทดลอง และค้นพบคำตอบด้วยตัวเอง</p>${btn('รู้จัก Headstart','about','green')}</div><ol class="number-list"><li><b>01 /</b><div><h3>มองเห็นภาพ ก่อนจำสูตร</h3><p>สำรวจแนวคิดจากตัวอย่างที่พบได้ในชีวิตประจำวัน</p></div></li><li><b>02 /</b><div><h3>ลองทำ แล้วเรียนรู้จากคำตอบ</h3><p>ทบทวนผ่านกิจกรรม แบบฝึกหัด และห้องทดลองจำลอง</p></div></li><li><b>03 /</b><div><h3>มองเห็นพัฒนาการไปด้วยกัน</h3><p>นักเรียนและผู้ปกครองติดตามการเรียนรู้และข้อเสนอแนะจากครู</p></div></li></ol></div></section><div class="container"><section class="section"><div class="heading-row"><div><div class="eyebrow">LEARNING BEYOND THE LESSON</div><h2>ความรู้ใหม่ ไม่ได้อยู่แค่ในบทเรียน</h2><p>บทความ ห้องทดลอง และกิจกรรมสำหรับคนช่างสงสัย</p></div><a class="text-link" href="#resources">สำรวจแหล่งเรียนรู้ ↗</a></div><div class="grid"><article class="card card-body"><span class="tag">Science in Life</span><h3>ทำไมน้ำแข็งถึงลอยน้ำ?</h3><p>เริ่มต้นรู้จักความหนาแน่น จากสิ่งเล็ก ๆ ในแก้วน้ำ</p><a href="#article/density" class="text-link">อ่านบทความ ↗</a></article><article class="card card-body"><span class="tag blue">Interactive Lab</span><h3>ทดลองเรื่องแรงและการเคลื่อนที่</h3><p>ปรับแรงและมวล แล้วค้นพบความสัมพันธ์ด้วยตัวเอง</p><a href="#lab" class="text-link">เข้าห้องทดลอง ↗</a></article><article class="card card-body"><span class="tag gray">Trial lessons</span><h3>ลองเรียน ก่อนเลือกเส้นทาง</h3><p>พื้นที่สำหรับวิดีโอตัวอย่างที่โรงเรียนอนุมัติให้เผยแพร่</p><a href="#resources" class="text-link">ดูบทเรียนทดลอง ↗</a></article></div></section><section style="padding-bottom:65px"><div class="heading-row"><div><div class="eyebrow">LET’S EXPLORE TOGETHER</div><h2>กิจกรรมและเวิร์กช็อป</h2></div><a class="text-link" href="#events">ดูกิจกรรมทั้งหมด ↗</a></div>${eventRow(0)}</section><div class="cta"><div><h2>ก้าวแรกของการเรียนรู้ เริ่มได้วันนี้</h2><p>สำรวจหลักสูตร ทดลองเรียน แล้วค้นหาเส้นทางที่เหมาะกับคุณ</p></div>${btn('เริ่มสำรวจหลักสูตร','courses')}</div></div>`}
function about(){return `<div class="container">${intro('รู้จักเรา','เริ่มจากความสงสัย<br>เติบโตด้วยความเข้าใจ','Headstart Academics · แนวทางการเรียนรู้ในต้นแบบ')}<div class="split section"><div><div class="eyebrow">OUR PHILOSOPHY</div><h2>เรียนให้เข้าใจ<br>และนำไปใช้ได้จริง</h2><p>ต้นแบบนี้จัดเส้นทางการเรียนรู้จากคำถามและสถานการณ์ใกล้ตัว ไปสู่การทดลอง การฝึกฝน และการทบทวนพร้อมข้อเสนอแนะ</p><p>เนื้อหาปรัชญาและประวัติโรงเรียนฉบับจริงอยู่ระหว่างรอการยืนยันจาก Headstart Academics</p></div><div class="feature-box"><h2>Ask. Explore.<br>Understand.</h2><p>ทุกคนมีจังหวะการเรียนรู้ของตัวเอง</p>${btn('สำรวจบทเรียน','courses','green')}</div></div><section style="padding-bottom:60px"><h2>รู้จักทีมผู้สอน</h2><div class="grid"><article class="card card-body"><div class="teacher-initial">DT</div><h3>Dr. Toey</h3><p>รอประวัติ ภาพถ่าย และข้อมูลคุณวุฒิที่ได้รับการยืนยันจากโรงเรียน</p><span class="tag gray">ยังไม่มีข้อมูลรับรองเผยแพร่</span></article><article class="card card-body"><h3>ทีมผู้สอน Headstart</h3><p>โรงเรียนสามารถเพิ่มประวัติ ความเชี่ยวชาญ และหลักสูตรที่รับผิดชอบก่อนเปิดใช้งานจริง</p></article><article class="card card-body"><h3>ผลงานและความสำเร็จ</h3><p>จะแสดงเฉพาะข้อมูลและหลักฐานที่โรงเรียนอนุมัติ ไม่มีการสร้างผลการเรียนหรือรางวัลขึ้นเอง</p></article></div><h2 style="margin-top:50px">เสียงจากนักเรียนและผู้ปกครอง</h2>${empty('ยังไม่มีรีวิวที่อนุมัติ','เมื่อมีรีวิวที่ได้รับความยินยอมและตรวจสอบแล้ว จะเผยแพร่ในส่วนนี้')}<h2>ภาพกิจกรรมและสื่อการเรียนรู้</h2>${empty('รอภาพและรายละเอียดจากโรงเรียน','รองรับภาพเวิร์กช็อปและ Day Camp รวมถึงรายการสื่อ Lab and Learn และ Stick and Learn เมื่อยืนยันข้อมูลแล้ว')}</section></div>`}
function catalog(){return `<div class="container">${intro('หลักสูตร','ค้นพบหลักสูตรที่ใช่','ตัวอย่างหลักสูตรสำหรับสำรวจแนวทางการเรียนรู้ · รายละเอียดจริงรอโรงเรียนยืนยัน')}<div class="filters"><input id="search" aria-label="ค้นหาหลักสูตร" placeholder="ค้นหาหลักสูตร หรือสิ่งที่อยากเรียนรู้…"><select id="subject" aria-label="วิชา"><option value="">ทุกวิชา</option><option>วิทยาศาสตร์</option><option>ฟิสิกส์</option><option>เคมี</option></select><select id="level" aria-label="ระดับชั้น"><option value="">ทุกระดับชั้น</option><option>ประถมปลาย</option><option>มัธยมต้น</option><option>มัธยมปลาย</option></select></div><p id="result-count" aria-live="polite">3 หลักสูตรตัวอย่าง</p><div class="grid" id="course-results">${courses.map(c=>card(c)).join('')}</div><div class="notice" style="margin:35px 0 60px">การส่งคำขอเรียนยังไม่ให้สิทธิ์เข้าถึงหลักสูตร ผู้ดูแลจะตรวจสอบและกำหนดสิทธิ์ให้ภายหลัง</div></div>`}
function course(id){const c=courses.find(c=>c.id===id);if(!c)return empty('ไม่พบหลักสูตร','กลับไปที่เมนูหลักสูตรเพื่อเลือกใหม่');return `<div class="container">${intro('หลักสูตร / '+c.title,c.title,c.thai)}<div class="detail-top"><div><span class="tag">${c.subject}</span> <span class="tag gray">${c.level}</span><h2 style="margin-top:25px">เปลี่ยนความสงสัย ให้เป็นความเข้าใจ</h2><p>${c.desc}</p><h3>เหมาะสำหรับใคร</h3><p>ผู้เรียนอายุ ${c.age} · ระดับ${c.level}<br>พื้นฐานที่แนะนำ: อ่านและทำความเข้าใจโจทย์ตามระดับชั้นได้</p><h3>สิ่งที่จะได้เรียนรู้</h3><ul>${c.objectives.map(t=>`<li>${t}</li>`).join('')}</ul><h3 style="margin-top:35px">โครงสร้างหลักสูตรตัวอย่าง</h3>${c.modules.map((m,i)=>`<details ${i===0?'open':''}><summary>โมดูล ${i+1} · ${m}</summary><p>วิดีโอบทเรียน แบบฝึกหัด และแบบทดสอบทบทวน<br>โรงเรียนจะเพิ่มเนื้อหาที่ผ่านการอนุมัติก่อนเผยแพร่</p></details>`).join('')}</div><aside class="sticky-card"><div class="course-art ${c.style}"><span class="formula">${c.formula}</span></div><h3 style="margin-top:24px">ข้อมูลหลักสูตร</h3><p>ผู้สอน: รอโรงเรียนกำหนด<br>${c.lessons} บทเรียนตัวอย่าง<br>ระยะเวลาวิดีโอ: ยังไม่ระบุ<br>ระยะเวลาสิทธิ์: ตัวอย่าง 90 วันจากการมอบหมาย</p><button class="primary" data-enroll="${c.id}">ส่งคำขอเรียน ↗</button><p style="margin-top:15px;font-size:13px">คำขอไม่ให้สิทธิ์เรียนโดยอัตโนมัติ</p>${btn('ดูบทเรียนทดลอง','resources','')}</aside></div><div class="notice warning" style="margin:40px 0 70px">หลักสูตรตัวอย่างเพื่อทดสอบการใช้งาน ไม่ใช่ประกาศเปิดรับสมัครจริง</div></div>`}
function resources(){return `<div class="container">${intro('เรียนรู้ฟรี','พื้นที่เล็ก ๆ สำหรับความสงสัยใหญ่ ๆ','ทดลอง ค้นพบ และต่อยอดความรู้ไปกับเรา')}<div class="tabs" id="resource-tabs">${['ทั้งหมด','Science Simplified','Study Smarter','Exam Excellence'].map((t,i)=>`<button class="${i===0?'active':''}" data-category="${t}">${t}</button>`).join('')}</div><div class="grid" id="articles">${articleCards('ทั้งหมด')}</div><section class="section"><h2>บทเรียนวิดีโอทดลอง</h2>${empty('ยังไม่มีวิดีโอที่ได้รับอนุมัติ','โรงเรียนต้องเพิ่มวิดีโอที่มีสิทธิ์เผยแพร่ก่อนเปิดบทเรียนทดลอง ไม่มีการจำลองว่าวิดีโอพร้อมเล่น')}<h2>ทดลองวิทยาศาสตร์ด้วยตัวเอง</h2><div class="panel"><span class="tag">Interactive Lab</span><h3 style="margin-top:18px">แรง มวล และความเร่ง</h3><p>ปรับตัวแปรเพื่อสำรวจสมการ F = ma ในห้องทดลองจำลองที่แยกจากระบบหลัก</p>${btn('เปิดห้องทดลอง','lab')}</div></section></div>`}
const articles=[['Science Simplified','ทำไมน้ำแข็งถึงลอยน้ำ?','density','ความหนาแน่นอธิบายปรากฏการณ์ใกล้ตัวได้อย่างไร'],['Study Smarter','ทบทวนให้จำได้นานขึ้น','study','ลองอธิบายด้วยคำของตัวเอง แล้วกลับมาทบทวน'],['Exam Excellence','อ่านโจทย์อย่างเป็นขั้นตอน','exam','แยกข้อมูลที่โจทย์ให้ และสิ่งที่ต้องหา']];
function articleCards(cat){return articles.filter(a=>cat==='ทั้งหมด'||a[0]===cat).map(a=>`<article class="card card-body"><span class="tag">${a[0]}</span><h3>${a[1]}</h3><p>${a[3]}</p><a class="text-link" href="#article/${a[2]}">อ่านต่อ ↗</a></article>`).join('')}
function article(id){const a=articles.find(a=>a[2]===id)||articles[0];return `<div class="container narrow">${intro('เรียนรู้ฟรี',a[1],a[0]+' · บทความตัวอย่าง')}<article class="panel"><h2>${a[3]}</h2>${id==='density'?'<p>ความหนาแน่น คือ มวลต่อปริมาตรของสาร เมื่อมวลเท่ากัน สารที่มีปริมาตรมากกว่าจะมีความหนาแน่นน้อยกว่า</p><p>เมื่อน้ำแข็งตัว โครงสร้างของน้ำทำให้ปริมาตรเพิ่มขึ้น น้ำแข็งจึงมีความหนาแน่นน้อยกว่าน้ำในสถานะของเหลวและลอยอยู่ได้</p><h3>ลองคิดต่อ</h3><p>ถ้าน้ำแข็งมีความหนาแน่นมากกว่าน้ำ จะเกิดอะไรขึ้นกับน้ำแข็งในแก้ว?</p>':id==='study'?'<p>หลังเรียนจบ ลองปิดหนังสือแล้วเขียนสิ่งที่เข้าใจด้วยคำของตัวเอง ตรวจส่วนที่ยังไม่แน่ใจ แล้ววางแผนกลับมาทบทวนอีกครั้ง</p><h3>เริ่มจาก 3 คำถาม</h3><p>วันนี้เรียนเรื่องอะไร? อธิบายให้เพื่อนเข้าใจได้ไหม? ยังมีคำถามตรงไหน?</p>':'<p>อ่านโจทย์ให้ครบ ระบุสิ่งที่รู้และสิ่งที่ต้องหา เขียนหน่วยกำกับทุกครั้ง ก่อนเลือกความสัมพันธ์หรือสมการที่เหมาะสม</p><p>หลังคำนวณ ลองตรวจว่าคำตอบมีหน่วยถูกต้องและสอดคล้องกับสถานการณ์หรือไม่</p>'}<div class="notice">เนื้อหาตัวอย่าง รอโรงเรียนตรวจทานก่อนใช้ในหลักสูตรจริง</div></article><div class="actions">${btn('กลับไปแหล่งเรียนรู้','resources','')}</div></div>`}
function lab(){const html=`<!doctype html><html lang="th"><meta charset="utf-8"><style>body{font:16px system-ui;color:#152238;padding:25px;background:#f1f5e8}label{display:block;margin:20px 0}input{width:65%;accent-color:#152238}output{font-size:32px;font-weight:bold}p{line-height:1.7}</style><h2>F = ma</h2><label>แรง F: <b id="fv">10</b> N<br><input id="f" aria-label="แรง" type="range" min="0" max="50" value="10"></label><label>มวล m: <b id="mv">2</b> kg<br><input id="m" aria-label="มวล" type="range" min="1" max="10" value="2"></label><p>ความเร่ง a = <output id="a">5.00</output> m/s²</p><script>function update(){fv.textContent=f.value;mv.textContent=m.value;a.textContent=(f.value/m.value).toFixed(2)}f.oninput=m.oninput=update;<\/script></html>`;return `<div class="container narrow">${intro('ห้องทดลอง','แรง มวล และความเร่ง','สำรวจความสัมพันธ์ในแบบจำลองอย่างง่าย')}<iframe class="lab" title="ห้องทดลองแรงและมวล" sandbox="allow-scripts" srcdoc="${esc(html)}"></iframe><div class="panel"><h3>ลองตั้งคำถาม</h3><p>เมื่อมวลคงที่ ถ้าเพิ่มแรงเป็นสองเท่า ความเร่งเปลี่ยนอย่างไร?</p><p>แบบจำลองนี้สมมติว่าแรงที่กำหนดเป็นแรงลัพธ์ และมวลไม่เปลี่ยนตามเวลา</p></div>${btn('กลับไปเรียนรู้ฟรี','resources','')}<div style="height:50px"></div></div>`}
const events=[{title:'Science Discovery Workshop',day:'17',month:'ต.ค. 2569',time:'09:00–12:00 น.',place:'สถานที่ตัวอย่าง · ห้องกิจกรรม Headstart',deadline:'10 ตุลาคม 2569',capacity:12},{title:'Study Smarter: เตรียมพร้อมก่อนสอบ',day:'24',month:'ต.ค. 2569',time:'10:00–11:30 น.',place:'สถานที่ตัวอย่าง · ห้องกิจกรรม Headstart',deadline:'17 ตุลาคม 2569',capacity:8}];
function eventRow(i){const e=events[i],count=i?8:state.eventCount;return `<article class="event-row"><div class="date-box"><b>${e.day}</b>${e.month}</div><div><span class="tag ${i?'gray':''}">${i?'เต็มแล้ว':'เวิร์กช็อปฟรี'} · กิจกรรมตัวอย่าง</span><h3 style="margin-top:8px">${e.title}</h3><p>${e.time} · กิจกรรม ณ สถานที่จริง</p><p>${count}/${e.capacity} ที่นั่ง · ปิดรับ ${e.deadline}</p></div><button class="button ${i?'':'dark'}" data-event="${i}" ${count>=e.capacity?'disabled':''}>${count>=e.capacity?'ที่นั่งเต็ม':'ดูรายละเอียด ↗'}</button></article>`}
function eventsPage(){return `<div class="container">${intro('กิจกรรม','ค้นพบสิ่งใหม่ ไปด้วยกัน','เวิร์กช็อปและกิจกรรม ณ สถานที่จริง · ไม่มีการถ่ายทอดสดหรือห้องเรียนออนไลน์')}<div class="notice warning">วัน เวลา และจำนวนที่นั่งเป็นข้อมูลตัวอย่าง การลงทะเบียนในต้นแบบไม่ใช่การจองจริง</div>${events.map((e,i)=>eventRow(i)).join('')}<div style="height:70px"></div></div>`}
function contact(){return `<div class="container">${intro('ติดต่อเรา','มาค้นหาเส้นทางการเรียนรู้ด้วยกัน','Headstart Academics')}<div class="split" style="align-items:start;padding-bottom:70px"><div class="panel"><h2>ติดต่อโรงเรียน</h2><p>ข้อมูลติดต่อจะเผยแพร่เมื่อโรงเรียนยืนยัน</p><details open><summary>ที่อยู่และแผนที่</summary><p>ยังไม่มีข้อมูลสถานที่ที่ยืนยันแล้ว</p></details><details open><summary>อีเมลและโทรศัพท์</summary><p>รออีเมลและหมายเลขโทรศัพท์จากโรงเรียน</p></details><details open><summary>LINE Official Account</summary><p>ยังไม่ได้เชื่อมต่อ LINE OA</p></details></div><div class="panel"><h2>ฝากคำถามถึงเรา</h2><p>ฟอร์มสาธิตเท่านั้น ไม่มีการส่งข้อความ</p><form id="contact-form"><label>ชื่อสำหรับสาธิต<input required maxlength="80" placeholder="ใช้ชื่อสมมติ"></label><label>หัวข้อ<select><option>สอบถามหลักสูตร</option><option>กิจกรรมและเวิร์กช็อป</option><option>ข้อมูลอื่น ๆ</option></select></label><label>คำถาม<textarea required maxlength="1000" placeholder="อย่าใส่ข้อมูลส่วนบุคคลจริง"></textarea></label><button class="primary">ตรวจสอบข้อความตัวอย่าง</button></form></div></div></div>`}
function login(){return `<div class="container narrow">${intro('เข้าสู่ระบบ','พื้นที่การเรียนรู้ของคุณ','เรียนต่อ ติดตามพัฒนาการ และเชื่อมต่อกับครู')}<div class="auth-box"><h2>เข้าสู่ระบบ</h2><div class="notice warning">ยังไม่เชื่อมต่อระบบบัญชีจริง โปรดใช้บทบาทสาธิตด้านล่าง ห้ามกรอกรหัสผ่านจริง</div><form id="login-form"><label>อีเมล<input type="email" placeholder="อีเมลของคุณ" disabled></label><label>รหัสผ่าน<input type="password" placeholder="ยังไม่เปิดใช้งาน" disabled></label><button class="primary" disabled>เข้าสู่ระบบด้วยอีเมล</button></form><div class="inline-actions" style="margin-top:20px"><a class="text-link" href="#reset">ลืมรหัสผ่าน</a><a class="text-link" href="#register">สมัครเป็นนักเรียน</a></div><hr style="border:0;border-top:1px solid var(--line);margin:30px 0"><h3>ลองใช้งานพื้นที่การเรียนรู้</h3><p>เลือกบทบาทเพื่อสำรวจข้อมูลตัวอย่าง ไม่ใช่การยืนยันตัวตน</p><div class="role-options">${Object.entries(roles).map(([r,t])=>`<button data-role="${r}">${t} ↗</button>`).join('')}</div></div></div>`}
function register(){return `<div class="container narrow">${intro('สมัครสมาชิก','เริ่มต้นการเรียนรู้','ตัวอย่างแบบฟอร์มสมัครสมาชิก · ไม่สร้างบัญชีจริง')}<div class="auth-box"><div class="notice warning">ใช้ข้อมูลสมมติเท่านั้น ไม่มีการส่งหรือบันทึกข้อมูลนี้</div><form id="register-form"><label>ประเภทบัญชี<select id="reg-role"><option value="student">นักเรียน</option><option value="parent">ผู้ปกครอง</option></select></label><div class="two"><label>ชื่อ<input required maxlength="60" autocomplete="off"></label><label>นามสกุล<input required maxlength="60" autocomplete="off"></label></div><label>อีเมล<input required type="email" autocomplete="off"></label><label>หมายเลขโทรศัพท์<input required pattern="[0-9+ ()-]{8,20}" autocomplete="off"></label><div id="student-fields"><div class="two"><label>อายุ<input type="number" required min="5" max="99"></label><label>ระดับชั้น<select><option>ประถมปลาย</option><option>มัธยมต้น</option><option>มัธยมปลาย</option><option>อื่น ๆ</option></select></label></div><label>อีเมลผู้ปกครอง<input required type="email"></label><label>โรงเรียน<input required maxlength="100"></label></div><label>ช่องทางติดต่ออื่น (ถ้ามี)<input maxlength="100"></label><p>ผู้ปกครองต้องได้รับคำเชิญหรือการอนุมัติความสัมพันธ์ก่อนเห็นข้อมูลบุตรหลาน การทราบอีเมลนักเรียนไม่ให้สิทธิ์เข้าถึง</p><button class="primary">ตรวจสอบแบบฟอร์มตัวอย่าง</button></form></div></div>`}
function portal(page='overview'){if(!state.role)return login();const r=state.role;const menus=r==='student'?[['overview','ภาพรวมการเรียน'],['learn','หลักสูตรของฉัน'],['assess','แบบทดสอบและงาน'],['messages','คำถามและข้อความ'],['certificates','ใบประกาศนียบัตร']]:r==='parent'?[['overview','ภาพรวมบุตรหลาน'],['reports','ผลการเรียนและรายงาน'],['messages','ข้อความถึงครู']]:r==='teacher'?[['overview','ภาพรวมการสอน'],['grading','ตรวจงานและให้คะแนน'],['reports','รายงานผู้ปกครอง'],['messages','คำถามและข้อความ']]:[['overview','ภาพรวมโรงเรียน'],['users','ผู้ใช้และสิทธิ์การเรียน'],['manage','จัดการหลักสูตร'],['eventadmin','จัดการกิจกรรม'],['content','เนื้อหาเว็บไซต์'],['reports','รายงานการเรียน']];return `<div class="portal"><aside class="sidebar"><div class="profile"><b>${roles[r]}สาธิต</b><small>Headstart Learning</small></div>${menus.map(([id,t])=>`<a href="#portal/${id}" class="${page===id?'active':''}">${t}</a>`).join('')}<a href="#login" data-signout>ออกจากโหมดสาธิต ↗</a></aside><div class="portal-content"><div class="heading-row"><div><div class="eyebrow">MY HEADSTART / ${r.toUpperCase()}</div><h1>${page==='overview'?(r==='student'?'พร้อมค้นพบอะไรใหม่ ๆ แล้วหรือยัง?':r==='parent'?'ทุกก้าวการเรียนรู้ มองเห็นได้ด้วยกัน':r==='teacher'?'วันนี้ มีการเรียนรู้ให้ดูแล':'ภาพรวม Headstart Academics'):menus.find(m=>m[0]===page)?.[1]||'พื้นที่การเรียนรู้'}</h1></div><span class="tag gray">ข้อมูลสาธิต</span></div><div class="notice">พื้นที่สาธิต ไม่มีการยืนยันตัวตนหรือสิทธิ์จริง ข้อมูลเปลี่ยนเฉพาะหน้านี้และรีเซ็ตเมื่อโหลดใหม่</div>${portalBody(page,r)}</div></div>`}
function stats(items){return `<div class="stats">${items.map(([v,t])=>`<div class="stat"><strong>${v}</strong><span>${t}</span></div>`).join('')}</div>`}
function portalBody(page,r){const allowed={student:['overview','learn','assess','messages','certificates'],parent:['overview','reports','messages'],teacher:['overview','grading','reports','messages'],admin:['overview','users','manage','eventadmin','content','reports']};if(!allowed[r].includes(page))return empty('หน้านี้ไม่อยู่ในบทบาทสาธิตที่เลือก','เลือกเมนูด้านข้างเพื่อดำเนินการต่อ');if(page==='learn')return lesson();if(page==='assess')return assessment();if(page==='messages')return messages();if(page==='certificates')return `<div class="panel"><h2>ใบประกาศนียบัตร</h2><p>กติกาตัวอย่าง: เรียนครบ 8 บท และคะแนนแบบทดสอบอย่างน้อย 60%</p>${state.done.size===8&&state.score>=60?'<div class="notice"><h3>ผ่านเกณฑ์ตัวอย่างแล้ว</h3>Science Explorer · ใบประกาศฉบับจริงต้องให้โรงเรียนกำหนดรูปแบบและอนุมัติ</div>':empty('ยังไม่มีใบประกาศนียบัตร','เรียนครบทุกบทและผ่านแบบทดสอบตามเกณฑ์ก่อนรับใบประกาศ')}</div>`;if(page==='users')return users();if(page==='manage')return manage();if(page==='eventadmin')return eventAdmin();if(page==='content')return contentAdmin();if(page==='grading')return grading();if(page==='reports')return reports(r);if(r==='student')return `${stats([[state.assigned?1:0,'หลักสูตรที่ได้รับมอบหมาย'],[state.done.size+'/8','บทเรียนที่เสร็จแล้ว'],[state.score===null?'—':state.score+'%','คะแนนแบบทดสอบ'],[state.grade===null?1:0,'งานที่รอผลประเมิน']])}<div class="heading-row"><h2>เรียนต่อจากครั้งที่แล้ว</h2><span class="tag">สิทธิ์ถึง ${state.access}</span></div><div class="grid">${state.assigned?card(courses[0],true):empty('ยังไม่มีหลักสูตรที่ได้รับมอบหมาย','รอผู้ดูแลกำหนดสิทธิ์หลังตรวจสอบคำขอ')}<div class="card card-body"><div class="eyebrow">YOUR NEXT STEP</div><h3>แบบฝึกหัด: สังเกตสิ่งรอบตัว</h3><p>กำหนดส่งตัวอย่าง 30 ตุลาคม 2569<br>บันทึกสิ่งที่สงสัย พร้อมอธิบายวิธีค้นหาคำตอบ</p>${btn('ดูงานและแบบทดสอบ','portal/assess','')}</div></div><div class="panel"><h3>ข้อเสนอแนะจากครู</h3><p>${esc(state.feedback)||'ยังไม่มีข้อเสนอแนะที่บันทึกในรอบสาธิตนี้'}</p></div>`;if(r==='parent')return `<label>เลือกบุตรหลานที่ได้รับการยืนยัน<select id="child"><option ${state.child==='เมฆ'?'selected':''}>เมฆ</option><option ${state.child==='ฟ้า'?'selected':''}>ฟ้า</option></select></label><span class="tag">ความสัมพันธ์ที่อนุมัติแล้ว · ข้อมูลสมมติ</span>${state.child==='ฟ้า'?empty('ฟ้า · ยังไม่มีหลักสูตร','ผู้ดูแลยังไม่ได้มอบหมายหลักสูตรให้บุตรหลานคนนี้'):`${stats([[state.done.size+'/8','บทเรียนที่เสร็จแล้ว'],[Math.round(state.done.size/8*100)+'%','ความก้าวหน้าจากบทเรียน'],[state.score===null?'—':state.score+'%','คะแนนแบบทดสอบ'],[state.grade===null?1:0,'งานที่ยังไม่ประเมิน']])}<div class="panel"><h3>Science Explorer · เมฆ</h3><progress value="${state.done.size}" max="8"></progress><p>เรียนแล้ว ${state.done.size} จาก 8 บท · สิทธิ์ถึง ${state.access}</p><p>ติดตามการเรียนวิดีโอและบทเรียนที่ทำเสร็จ ไม่ใช่การเช็กชื่อเข้าห้องเรียน</p>${btn('ดูผลและข้อเสนอแนะ','portal/reports','')}</div>`}`;if(r==='teacher')return `${stats([[1,'หลักสูตรที่รับผิดชอบ'],[1,'นักเรียนที่ได้รับมอบหมาย'],[state.grade===null?1:0,'งานรอตรวจ'],[state.messages.filter(m=>m.role==='student').length,'คำถามนักเรียนในรอบสาธิต']])}<div class="grid"><div class="panel"><h3>งานที่ต้องดูแล</h3><p>เมฆ · แบบฝึกหัดการสังเกตสิ่งรอบตัว</p>${btn('ตรวจงาน','portal/grading')}</div><div class="panel"><h3>นักเรียนใน Science Explorer</h3><p>เมฆ · เรียนแล้ว ${state.done.size}/8 บท</p><progress value="${state.done.size}" max="8"></progress>${btn('เตรียมรายงานผู้ปกครอง','portal/reports','')}</div></div>`;return `${stats([[1,'นักเรียนตัวอย่าง'],[state.assigned?1:0,'สิทธิ์หลักสูตรที่ใช้งาน'],[state.done.size===8?1:0,'หลักสูตรที่เรียนครบ'],[state.registrations.length,'การลงทะเบียนรอบสาธิต']])}<div class="grid"><div class="panel"><h3>คำขอเรียนที่รอตรวจสอบ</h3><p>${state.requests.length} คำขอใหม่ในรอบสาธิตนี้</p>${btn('จัดการผู้ใช้และสิทธิ์','portal/users')}</div><div class="panel"><h3>ความก้าวหน้าการเรียน</h3><p>Science Explorer · นักเรียนสาธิต 1 คน</p><progress value="${state.done.size}" max="8"></progress><p>เรียนครบ ${Math.round(state.done.size/8*100)}% · คะแนน ${state.score===null?'ยังไม่มี':state.score+'%'}</p></div></div>`}
const lessonNames=['รู้จักกระบวนการทางวิทยาศาสตร์','การสังเกตและตั้งคำถาม','ตั้งสมมติฐานอย่างมีเหตุผล','สสารรอบตัวเรา','สถานะของสาร','การเปลี่ยนแปลงของสสาร','ออกแบบการทดลอง','ทบทวนสิ่งที่ค้นพบ'];
function lesson(){if(!state.assigned)return empty('ยังไม่มีสิทธิ์เรียนหลักสูตรนี้','ผู้ดูแลต้องมอบหมายสิทธิ์ให้ก่อน');return `<div class="learning"><div><div class="video-empty"><span class="play-icon">▷</span><h3>${lessonNames[state.lesson]}</h3><p>ยังไม่ได้เพิ่มวิดีโอที่ได้รับอนุมัติ<br>พื้นที่นี้รองรับวิดีโอที่บันทึกไว้ล่วงหน้า</p></div><div class="panel"><span class="tag">Science Explorer</span><h2 style="margin-top:15px">บทที่ ${state.lesson+1} · ${lessonNames[state.lesson]}</h2><p>สิทธิ์เรียนถึง ${state.access} · ไม่มีการบันทึกการดูวิดีโอจริงในต้นแบบ</p><button class="primary" id="complete">${state.done.has(state.lesson)?'ยกเลิกสถานะเรียนจบตัวอย่าง':'ทำเครื่องหมายเรียนจบตัวอย่าง'}</button><div class="tabs"><a class="text-link" href="#portal/assess">แบบฝึกหัดและแบบทดสอบ ↗</a><a class="text-link" href="#portal/messages">ถามคำถามกับครู ↗</a></div><h3>เอกสารประกอบ</h3><p>ยังไม่มีไฟล์ที่ได้รับอนุมัติให้ดาวน์โหลด</p></div></div><aside><h3>บทเรียนทั้งหมด</h3><p>${state.done.size}/8 บทเรียน</p><progress value="${state.done.size}" max="8"></progress>${lessonNames.map((t,i)=>`<button class="lesson-row ${i===state.lesson?'active':''}" data-lesson="${i}">${state.done.has(i)?'✓':'○'} ${i+1}. ${t}<small>วิดีโอ · รอเพิ่มเนื้อหา</small></button>`).join('')}</aside></div>`}
function assessment(){return `<div class="panel"><span class="tag">แบบทดสอบหลังเรียน · ตัวอย่าง</span><h2 style="margin-top:15px">เข้าใจแรงและการเคลื่อนที่</h2><p>ผ่านที่ 60% · ทำได้ 2 ครั้ง · ใช้แล้ว ${state.attempts}/2 ครั้ง · แสดงคะแนนหลังส่งเท่านั้น</p>${state.score!==null?`<div class="notice">ผลล่าสุด ${state.score}% · ${state.score>=60?'ผ่านเกณฑ์ตัวอย่าง':'ยังไม่ผ่านเกณฑ์'} · ไม่เปิดเฉลยตามการตั้งค่าตัวอย่าง</div>`:''}<form id="quiz"><fieldset style="border:0;padding:0"><legend>1. เมื่อแรงลัพธ์คงที่ หากเพิ่มมวลเป็นสองเท่า ความเร่งจะเป็นอย่างไร?</legend>${['เพิ่มเป็นสองเท่า','ลดลงครึ่งหนึ่ง','เท่าเดิม'].map((t,i)=>`<label class="question-option"><input required type="radio" name="q1" value="${i}">${t}</label>`).join('')}</fieldset><fieldset style="border:0;padding:0;margin:25px 0"><legend>2. หน่วย SI ของแรงคืออะไร?</legend>${['นิวตัน','กิโลกรัม','เมตร'].map((t,i)=>`<label class="question-option"><input required type="radio" name="q2" value="${i}">${t}</label>`).join('')}</fieldset><button class="primary" ${state.attempts>=2?'disabled':''}>${state.attempts>=2?'ครบจำนวนครั้งแล้ว':'ส่งคำตอบตัวอย่าง'}</button></form><p style="font-size:13px;margin-top:15px">ต้นแบบตรวจคะแนนในเบราว์เซอร์ ไม่เหมาะสำหรับข้อสอบจริง ระบบจริงต้องตรวจและเก็บเฉลยบนเซิร์ฟเวอร์</p></div><div class="panel"><h2>ส่งการบ้าน</h2><p>แบบฝึกหัด: สังเกตสิ่งรอบตัว · กำหนดส่งตัวอย่าง 30 ต.ค. 2569</p><form id="homework"><label>คำตอบแบบเขียน<textarea required maxlength="2000" placeholder="คำตอบตัวอย่าง ไม่ใช้ข้อมูลจริง"></textarea></label><label>ไฟล์ประกอบ · PDF, JPG, PNG ไม่เกิน 5 MB<input type="file" id="homework-file" accept=".pdf,.jpg,.jpeg,.png"></label><p>ไฟล์จะถูกตรวจสอบในเครื่องเท่านั้น ไม่ถูกอัปโหลด</p><button class="primary">ตรวจสอบงานตัวอย่าง</button></form>${state.grade!==null?`<div class="notice">คะแนนจากครู ${state.grade}/10 · ${esc(state.feedback)}</div>`:''}</div><div class="panel"><h3>Placement Test และ Pre-test</h3><p>ยังไม่มีข้อสอบวัดระดับที่โรงเรียนตั้งค่า คำแนะนำหลักสูตรต้องอ้างอิงเกณฑ์ของโรงเรียน และไม่ให้สิทธิ์เรียนอัตโนมัติ</p></div>`}
function messages(){return `<div class="panel"><h2>Science Explorer · พื้นที่สนทนา</h2><p>คำถามนักเรียนและข้อความผู้ปกครองในรอบสาธิตนี้</p>${state.messages.filter(m=>!m.hidden).map(m=>`<div class="message"><b>${roles[m.role]}สาธิต ${m.audience==='parent'?'· ข้อความผู้ปกครอง':'· คำถามในหลักสูตร'}</b><p>${esc(m.text)}</p>${state.role==='teacher'?`<button class="button small" data-hide="${m.id}">ซ่อนข้อความตัวอย่าง</button>`:''}</div>`).join('')||empty('ยังไม่มีข้อความ','ลองเขียนคำถามหรือข้อเสนอแนะด้วยข้อมูลสมมติ')}<form id="message-form"><label>ประเภทข้อความ<select name="audience"><option value="course">คำถามในหลักสูตร</option><option value="parent">ข้อความถึงครู / ผู้ปกครอง</option></select></label><label>ข้อความ<textarea name="text" required maxlength="1000" placeholder="ข้อความสาธิต ไม่มีการส่งถึงบุคคลจริง"></textarea></label><button class="primary">เพิ่มข้อความในรอบสาธิต</button></form></div>`}
function users(){return `<div class="panel"><div class="heading-row"><h2>นักเรียนและสิทธิ์หลักสูตร</h2><button class="button small" id="invite">สร้างคำเชิญตัวอย่าง</button></div><div class="table-scroll"><table><thead><tr><th>นักเรียน</th><th>หลักสูตร</th><th>ระยะเวลาสิทธิ์</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr><td>เมฆ (สมมติ)</td><td>Science Explorer</td><td>${state.access}</td><td>${state.assigned?'ได้รับมอบหมาย':'เพิกถอนแล้ว'}</td><td><button class="button small" id="toggle-access">${state.assigned?'เพิกถอน':'มอบหมาย'}สิทธิ์ตัวอย่าง</button></td></tr></tbody></table></div><form id="access-form" style="margin-top:20px"><div class="two"><label>รูปแบบสิทธิ์<select id="access-mode"><option value="date">วันสิ้นสุด</option><option value="duration">ระยะเวลาจากการมอบหมาย</option><option value="unlimited">ไม่จำกัด (กำหนดโดยชัดแจ้ง)</option></select></label><label>วันสิ้นสุด<input id="access-date" type="date" value="2026-12-31"></label></div><button class="primary">บันทึกสิทธิ์ตัวอย่าง</button></form></div><div class="panel"><h2>คำขอเรียน</h2>${state.requests.length?state.requests.map(c=>`<div class="message"><b>${esc(c.title)}</b><p>ผู้เรียนสาธิต · รอผู้ดูแลตรวจสอบ</p></div>`).join(''):empty('ยังไม่มีคำขอ','คำขอจากหน้าหลักสูตรจะปรากฏที่นี่ในรอบสาธิตเดียวกัน')}</div><div class="panel"><h2>ความสัมพันธ์ผู้ปกครอง</h2><p>ผู้ปกครองตัวอย่างเชื่อมกับ เมฆ และ ฟ้า · ความสัมพันธ์สมมติที่ได้รับการอนุมัติแล้ว</p><p>ระบบจริงต้องรองรับผู้ปกครองหลายคนต่อนักเรียน และการยืนยันด้วยคำเชิญหรือผู้ดูแลอนุมัติ ไม่ค้นหาความสัมพันธ์จากอีเมลอย่างเดียว</p><button class="button" id="guardian">ดูขั้นตอนเชื่อมบัญชี</button></div>`}
function manage(){return `<div class="panel"><h2>Science Explorer</h2><form id="course-form"><div class="two"><label>ชื่อหลักสูตร<input name="title" required value="${esc(courses[0].title)}" maxlength="80"></label><label>สถานะ<select name="status">${['ร่าง','เผยแพร่ตัวอย่าง','เก็บถาวร'].map(s=>`<option ${state.publication===s?'selected':''}>${s}</option>`).join('')}</select></label></div><label>คำอธิบาย<textarea name="desc" required maxlength="1000">${esc(courses[0].desc)}</textarea></label><label>ครูที่ได้รับมอบหมาย<select><option>ครูสาธิต</option></select></label><button class="primary">บันทึกหลักสูตรตัวอย่าง</button></form></div><div class="panel"><h3>โมดูลและบทเรียน</h3>${courses[0].modules.map((m,i)=>`<details><summary>${i+1}. ${m}</summary><p>วิดีโอที่บันทึกไว้ล่วงหน้าและไฟล์ประกอบ · ยังไม่ได้เชื่อมต่อพื้นที่เก็บไฟล์ส่วนตัว</p></details>`).join('')}<div class="notice warning">ยังไม่รองรับการอัปโหลดวิดีโอหรือไฟล์จริง ต้องกำหนดพื้นที่จัดเก็บและการตรวจสิทธิ์ก่อนเปิดใช้</div><button class="button" id="lesson-settings">ตั้งค่าบทเรียนตัวอย่าง</button></div><div class="panel"><h3>การประเมินผล</h3><p>กติกาสาธิต: คะแนนผ่าน 60% · ทำได้ 2 ครั้ง · ไม่เปิดเฉลย · ใบประกาศเมื่อเรียนครบทุกบทและสอบผ่าน</p><p>ระบบจัดการข้อสอบ การอัปโหลดไฟล์ข้อสอบ และเกณฑ์แนะนำหลักสูตรยังต้องพัฒนาฝั่งเซิร์ฟเวอร์</p></div>`}
function eventAdmin(){return `<div class="panel"><h2>การลงทะเบียนกิจกรรม</h2><p>Science Discovery Workshop · ${state.eventCount}/12 ที่นั่ง รวมข้อมูลตั้งต้น 6 ที่นั่ง</p>${state.registrations.length?`<div class="table-scroll"><table><thead><tr><th>รหัสสาธิต</th><th>กิจกรรม</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${state.registrations.map((r,i)=>`<tr><td>${r.id}</td><td>Science Discovery</td><td>${r.cancelled?'ยกเลิกแล้ว':'ยืนยันในต้นแบบ'}</td><td><button class="button small" data-cancel="${i}" ${r.cancelled?'disabled':''}>ยกเลิกการลงทะเบียน</button></td></tr>`).join('')}</tbody></table></div>`:empty('ยังไม่มีการลงทะเบียนใหม่','ทดลองลงทะเบียนจากหน้ากิจกรรมเพื่อดูรายการที่นี่')}<div class="notice">ไม่มีการส่งอีเมลยืนยันจริง การจองที่นั่งพร้อมกันหลายคนต้องใช้ระบบฐานข้อมูลในเวอร์ชันจริง</div></div>`}
function contentAdmin(){return `<div class="panel"><h2>เนื้อหาสาธารณะที่รอข้อมูล</h2>${['ประวัติโรงเรียนและปรัชญา','ประวัติ Dr. Toey และครูผู้สอน','คุณวุฒิ รางวัล และผลงานที่ตรวจสอบแล้ว','รีวิวที่ได้รับความยินยอม','รูปภาพกิจกรรมและสิทธิ์การเผยแพร่','วิดีโอบทเรียนทดลองที่อนุมัติ','ข้อมูลติดต่อและ LINE OA','Lab and Learn / Stick and Learn'].map(t=>`<details><summary>${t}</summary><p>ยังไม่มีข้อมูลที่โรงเรียนอนุมัติ จึงยังไม่เผยแพร่</p></details>`).join('')}<div class="notice">ตัวแก้ไขเนื้อหาถาวรและขั้นตอนอนุมัติยังไม่ได้เชื่อมต่อ</div></div>`}
function grading(){return `<div class="panel"><span class="tag">งานเขียน · ครูตรวจเอง</span><h2 style="margin-top:18px">เมฆ · สังเกตสิ่งรอบตัว</h2><div class="message"><b>คำตอบตัวอย่าง</b><p>${esc(state.homework)||'ฉันสงสัยว่าน้ำแข็งทำไมถึงลอยน้ำ จึงอยากทดลองเปรียบเทียบมวลกับปริมาตรของน้ำและน้ำแข็ง'}</p></div><form id="grading-form"><label>คะแนน (0–10)<input name="grade" required type="number" min="0" max="10" step="0.5" value="${state.grade??''}"></label><label>ข้อเสนอแนะจากครู<textarea name="feedback" required maxlength="1000">${esc(state.feedback)}</textarea></label><button class="primary">บันทึกผลประเมินตัวอย่าง</button></form></div>`}
function reports(r){return `<div class="panel"><span class="tag">รายงานจากสถานะในรอบสาธิต</span><h2 style="margin-top:15px">${r==='parent'&&state.child==='ฟ้า'?'ฟ้า':'เมฆ'} · สรุปการเรียนรู้</h2>${r==='parent'&&state.child==='ฟ้า'?empty('ยังไม่มีข้อมูลการเรียน','ฟ้ายังไม่ได้รับมอบหมายหลักสูตร'):`${stats([[state.done.size+'/8','บทเรียนที่ทำเสร็จ'],[Math.round(state.done.size/8*100)+'%','ความก้าวหน้า'],[state.score===null?'—':state.score+'%','ผลแบบทดสอบ'],[state.grade===null?'รอตรวจ':state.grade+'/10','คะแนนงานเขียน']])}<h3>งานที่ยังไม่เสร็จ</h3><p>${state.homework?'ส่งคำตอบตัวอย่างแล้ว':'แบบฝึกหัดสังเกตสิ่งรอบตัว · กำหนดส่งตัวอย่าง 30 ต.ค. 2569'}</p><h3>ข้อเสนอแนะจากครู</h3><p>${esc(state.feedback)||'ยังไม่มีข้อเสนอแนะที่บันทึกไว้'}</p>`}${r==='teacher'?`<form id="report-form"><label>ความเห็นเพิ่มเติมก่อนส่งรายงาน<textarea name="comment" required maxlength="1000">${esc(state.reportComment||'')}</textarea></label><button class="primary">บันทึกร่างรายงานตัวอย่าง</button></form><div class="notice">ยังไม่เชื่อมต่ออีเมลหรือ LINE OA ไม่มีการส่งรายงาน การแจ้งเตือนจริงควรมีเพียงลิงก์ไปยังรายงานในระบบ</div>`:''}${r==='parent'&&state.reportComment?`<div class="message"><h3>ความเห็นเพิ่มเติมจากครู</h3><p>${esc(state.reportComment)}</p></div>`:''}</div>`}
function status(){return `<div class="container">${intro('สถานะระบบ','ต้นแบบที่ลองใช้งานได้','สิ่งที่พร้อมทดลอง และสิ่งที่ต้องเชื่อมต่อก่อนใช้งานจริง')}<div class="two"><div class="panel"><h2>ทดลองได้ในเวอร์ชันนี้</h2><ul><li>เว็บไซต์ภาษาไทยและหน้าจอที่ปรับตามอุปกรณ์</li><li>ค้นหาและกรองหลักสูตร ดูรายละเอียด ส่งคำขอจำลอง</li><li>บทความและห้องทดลองที่แยกด้วย sandbox</li><li>ลงทะเบียนกิจกรรมจำลอง พร้อมสถานะเต็มและยกเลิก</li><li>มุมมองนักเรียน ผู้ปกครอง ครู และผู้ดูแล</li><li>ความก้าวหน้า แบบทดสอบ งานเขียน การตรวจงาน และข้อความในรอบสาธิต</li><li>ตั้งสิทธิ์หลักสูตรและแก้ไขข้อมูลหลักสูตรตัวอย่าง</li></ul></div><div class="panel"><h2>ยังไม่พร้อมสำหรับข้อมูลจริง</h2><ul><li>ไม่มีฐานข้อมูลถาวรหรือระบบยืนยันตัวตน</li><li>ไม่มีการบังคับสิทธิ์บนเซิร์ฟเวอร์ บทบาทเป็นการสาธิต</li><li>ยังไม่มีบัญชี คำเชิญตั้งรหัสผ่าน หรือรีเซ็ตรหัสผ่านจริง</li><li>ยังไม่เชื่อมต่ออีเมล LINE OA วิดีโอ หรือพื้นที่เก็บไฟล์</li><li>ยังไม่ป้องกันเฉลยในเบราว์เซอร์สำหรับการสอบจริง</li><li>ใบประกาศ การจัดการข้อสอบ และการเผยแพร่เนื้อหาถาวรยังต้องพัฒนา</li></ul></div></div><div class="notice warning">ห้ามใช้ข้อมูลนักเรียนจริง รหัสผ่านจริง หรือเอกสารส่วนตัวในต้นแบบ ข้อมูลการโต้ตอบอยู่ในหน่วยความจำของหน้านี้และหายเมื่อโหลดใหม่</div><div class="panel"><h3>ข้อมูลที่ต้องการจากโรงเรียน</h3><p>HS Website.pdf, โลโก้, รายละเอียดหลักสูตร, ประวัติครูที่ยืนยันแล้ว, วิดีโอที่มีสิทธิ์เผยแพร่, รีวิวและภาพที่ได้รับความยินยอม และช่องทางติดต่อจริง</p><p>English: โครงสร้างเนื้อหาและการนำทางใช้รหัสหน้าที่คงที่ พร้อมแยกข้อความเป็นชุดภาษาในขั้นพัฒนาต่อ ยังไม่มีคำแปลภาษาอังกฤษ</p></div><div style="height:40px"></div></div>`}
function render(){const [route='home',id]=(location.hash.slice(1)||'home').split('/');document.title=`${({home:'หน้าแรก',courses:'หลักสูตร',about:'รู้จักเรา',resources:'เรียนรู้ฟรี',events:'กิจกรรม',portal:'My Learning'})[route]||'Headstart Learning'} | Headstart Academics`;main.innerHTML=route==='home'?home():route==='about'?about():route==='courses'?catalog():route==='course'?course(id):route==='resources'?resources():route==='article'?article(id):route==='lab'?lab():route==='events'?eventsPage():route==='contact'?contact():route==='login'?login():route==='register'?register():route==='reset'?`<div class="container narrow">${intro('รหัสผ่าน','ตั้งรหัสผ่านใหม่','ยังไม่เชื่อมต่อบริการบัญชี')}<div class="notice warning">ยังไม่มีบัญชีจริงในต้นแบบ จึงไม่สามารถส่งลิงก์รีเซ็ตได้</div>${btn('กลับไปเข้าสู่ระบบ','login','')}<div style="height:70px"></div></div>`:route==='portal'?portal(id):route==='status'?status():empty('ไม่พบหน้านี้','เลือกเมนูด้านบนเพื่อไปยังหน้าที่ต้องการ');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('.signin').innerHTML=state.role?'My Learning ↗':'เข้าสู่ระบบ ↗';$('.signin').href=state.role?'#portal/overview':'#login';$('nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');bind()}
function refresh(){render()}
function bind(){if($('#search')){const filter=()=>{const q=$('#search').value.toLowerCase(),s=$('#subject').value,l=$('#level').value,cs=courses.filter(c=>(!s||c.subject===s)&&(!l||c.level===l)&&(c.title+c.thai+c.subject).toLowerCase().includes(q));$('#course-results').innerHTML=cs.map(c=>card(c)).join('')||empty('ยังไม่พบหลักสูตรที่ตรงกัน','ลองเปลี่ยนคำค้นหาหรือระดับชั้น');$('#result-count').textContent=cs.length+' หลักสูตรตัวอย่าง'};['#search','#subject','#level'].forEach(s=>$(s).addEventListener('input',filter))}
document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.role=b.dataset.role;location.hash='portal/overview'});document.querySelectorAll('[data-signout]').forEach(b=>b.onclick=()=>state.role=null);
document.querySelectorAll('[data-enroll]').forEach(b=>b.onclick=()=>{const c=courses.find(c=>c.id===b.dataset.enroll);modal(`<h2>ส่งคำขอเรียน</h2><p>${c.title} · การสาธิต</p><p>จะเพิ่มคำขอตัวอย่างให้ผู้ดูแลตรวจสอบ โดยไม่ให้สิทธิ์เข้าเรียน ไม่ส่งข้อมูลออกจากหน้านี้</p><button class="primary" id="confirm-enroll">ยืนยันคำขอจำลอง</button>`);$('#confirm-enroll').onclick=()=>{if(!state.requests.some(r=>r.id===c.id))state.requests.push(c);$('#modal').close();toast('เพิ่มคำขอตัวอย่างแล้ว · รอผู้ดูแลพิจารณา')}});
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));$('#articles').innerHTML=articleCards(b.dataset.category)});
document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{const e=events[+b.dataset.event];modal(`<span class="tag">กิจกรรมตัวอย่าง</span><h2 style="margin-top:15px">${e.title}</h2><p>สำรวจวิทยาศาสตร์ผ่านกิจกรรมและการทดลองที่ออกแบบให้ลงมือทำร่วมกัน</p><p>${e.day} ${e.month} · ${e.time}<br>${e.place}<br>ปิดรับ ${e.deadline} · รับ ${e.capacity} คน</p><div class="notice">ทดลองลงทะเบียน 1 ที่นั่งด้วยผู้เข้าร่วมสมมติ ไม่ใช่การจองกิจกรรมจริง</div><button class="primary" id="event-confirm">ลงทะเบียนจำลอง</button>`);$('#event-confirm').onclick=()=>{if(state.eventCount>=12){toast('ที่นั่งเต็มแล้ว');return}const id='DEMO-'+String(state.registrations.length+1).padStart(3,'0');state.registrations.push({id,cancelled:false});state.eventCount++;$('#modal-content').innerHTML=`<h2>ยืนยันการลงทะเบียนจำลอง</h2><p>รหัส ${id} · Science Discovery Workshop</p><div class="notice">บันทึกเฉพาะรอบสาธิตนี้ ไม่มีการจองจริงหรือส่งอีเมล</div>`;refresh()}});
if($('#contact-form'))$('#contact-form').onsubmit=e=>{e.preventDefault();toast('ตรวจสอบฟอร์มแล้ว · ไม่ได้ส่งข้อความ เพราะยังไม่เชื่อมต่อบริการ');e.target.reset()};
if($('#register-form'))$('#register-form').onsubmit=e=>{e.preventDefault();modal('<h2>แบบฟอร์มตัวอย่างครบถ้วน</h2><p>ยังไม่ได้สร้างบัญชีหรือส่งอีเมล กรุณาเลือกบทบาทสาธิตจากหน้าเข้าสู่ระบบเพื่อทดลองขั้นตอนถัดไป</p>');e.target.reset()};if($('#reg-role'))$('#reg-role').onchange=e=>{const hide=e.target.value==='parent';$('#student-fields').classList.toggle('hide',hide);$('#student-fields').querySelectorAll('input').forEach(x=>x.disabled=hide)};
if($('#complete'))$('#complete').onclick=()=>{state.done.has(state.lesson)?state.done.delete(state.lesson):state.done.add(state.lesson);refresh();toast('ปรับสถานะบทเรียนตัวอย่างแล้ว')};document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson=+b.dataset.lesson;refresh()});
if($('#child'))$('#child').onchange=e=>{state.child=e.target.value;refresh()};
if($('#quiz'))$('#quiz').onsubmit=e=>{e.preventDefault();if(state.attempts>=2)return;const f=new FormData(e.target);state.score=(f.get('q1')==='1'?50:0)+(f.get('q2')==='0'?50:0);state.attempts++;refresh();toast('ตรวจคำตอบตัวอย่างแล้ว')};
if($('#homework'))$('#homework').onsubmit=e=>{e.preventDefault();const f=$('#homework-file').files[0];if(f&&(!/\.(pdf|jpe?g|png)$/i.test(f.name)||f.size>5*1024*1024)){toast('เลือกไฟล์ PDF, JPG หรือ PNG ไม่เกิน 5 MB');return}state.homework=e.target.querySelector('textarea').value;toast('เก็บคำตอบในรอบสาธิตแล้ว · ไฟล์ไม่ได้อัปโหลด');e.target.reset()};
if($('#message-form'))$('#message-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.messages.push({id:Date.now(),role:state.role,text:f.get('text'),audience:f.get('audience')});refresh();toast('เพิ่มข้อความตัวอย่างแล้ว ไม่มีการส่งภายนอก')};document.querySelectorAll('[data-hide]').forEach(b=>b.onclick=()=>{state.messages.find(m=>m.id===+b.dataset.hide).hidden=true;refresh()});
if($('#toggle-access'))$('#toggle-access').onclick=()=>{state.assigned=!state.assigned;refresh();toast('ปรับสิทธิ์ในรอบสาธิตแล้ว')};if($('#access-mode'))$('#access-mode').onchange=e=>{const input=$('#access-date');input.disabled=e.target.value==='unlimited';input.type=e.target.value==='duration'?'number':'date';input.value=e.target.value==='duration'?'90':'2026-12-31';if(e.target.value==='duration'){input.min='1';input.max='3650'}else{input.removeAttribute('min');input.removeAttribute('max')}};
if($('#access-form'))$('#access-form').onsubmit=e=>{e.preventDefault();const mode=$('#access-mode').value,val=$('#access-date').value;if(mode!=='unlimited'&&!val){toast('กรุณากำหนดระยะเวลาสิทธิ์');return}state.access=mode==='unlimited'?'ไม่จำกัด':mode==='duration'?val+' วันจากการมอบหมาย':new Date(val+'T00:00:00').toLocaleDateString('th-TH',{year:'numeric',month:'long',day:'numeric'});refresh();toast('บันทึกเงื่อนไขสิทธิ์ตัวอย่างแล้ว')};
if($('#invite'))$('#invite').onclick=()=>modal('<h2>เชิญผู้ใช้ตั้งรหัสผ่าน</h2><p>ระบบจริงต้องสร้างลิงก์ใช้ครั้งเดียวที่มีวันหมดอายุ และส่งอีเมลให้เจ้าของบัญชีตั้งรหัสผ่านด้วยตัวเอง</p><div class="notice warning">ยังไม่เชื่อมต่อบริการบัญชีและอีเมล จึงยังไม่สร้างหรือส่งคำเชิญ</div>');
if($('#guardian'))$('#guardian').onclick=()=>modal('<h2>เชื่อมบัญชีผู้ปกครองอย่างปลอดภัย</h2><ol><li>ผู้ดูแลตรวจสอบความสัมพันธ์</li><li>ส่งคำเชิญเฉพาะผู้ปกครองที่อนุมัติ</li><li>ผู้ปกครองยืนยันคำเชิญด้วยบัญชีของตน</li><li>เซิร์ฟเวอร์ตรวจสิทธิ์ทุกครั้งที่อ่านข้อมูลบุตรหลาน</li></ol><p>รองรับหลายบุตรหลานและหลายผู้ปกครอง ขั้นตอนจริงยังไม่เชื่อมต่อในต้นแบบ</p>');
if($('#course-form'))$('#course-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);courses[0].title=f.get('title');courses[0].desc=f.get('desc');state.publication=f.get('status');toast('บันทึกข้อมูลตัวอย่างแล้ว · ไม่ได้เผยแพร่หรือเก็บถาวรจริง')};
if($('#lesson-settings'))$('#lesson-settings').onclick=()=>modal('<h2>การตั้งค่าบทเรียน</h2><p>บทเรียนตัวอย่างยังไม่มีวิดีโอ จึงยังตั้งเป็นบทเรียนทดลองสาธารณะไม่ได้</p><div class="notice">ก่อนเผยแพร่ ต้องเพิ่มวิดีโอที่มีสิทธิ์ใช้ กำหนดผู้เข้าถึง และตั้งค่าไฟล์ส่วนตัวบนระบบจริง</div>');
document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{state.registrations[+b.dataset.cancel].cancelled=true;state.eventCount--;refresh();toast('ยกเลิกที่นั่งตัวอย่างแล้ว')});
if($('#grading-form'))$('#grading-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.grade=+f.get('grade');state.feedback=f.get('feedback');toast('บันทึกคะแนนและข้อเสนอแนะในรอบสาธิตแล้ว')};
if($('#report-form'))$('#report-form').onsubmit=e=>{e.preventDefault();state.reportComment=new FormData(e.target).get('comment');toast('บันทึกร่างตัวอย่างแล้ว · ไม่มีการส่งอีเมลหรือ LINE')};}
$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_headstart',description:'Open a public Headstart prototype page. Does not register, enroll, authenticate, or send data.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['home','about','courses','resources','events','contact','login']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async({page})=>{if(!['home','about','courses','resources','events','contact','login'].includes(page))throw new Error('Invalid page');location.hash=page;render();return {page,prototype:true}}})).catch(()=>{})}catch{}}

